]$legacy_musicians$::jsonb)
  loop
    v_created_at := (item->>'created_at')::timestamptz;
    v_updated_at := (item->>'updated_at')::timestamptz;

    select id into v_user_id
    from auth.users
    where lower(email) = lower(item->>'email')
    limit 1;

    if v_user_id is null then
      v_user_id := (item->>'user_id')::uuid;

      insert into auth.users (
        instance_id,
        id,
        aud,
        role,
        email,
        encrypted_password,
        email_confirmed_at,
        invited_at,
        confirmation_sent_at,
        raw_app_meta_data,
        raw_user_meta_data,
        created_at,
        updated_at
      ) values (
        '00000000-0000-0000-0000-000000000000'::uuid,
        v_user_id,
        'authenticated',
        'authenticated',
        item->>'email',
        crypt(gen_random_uuid()::text, gen_salt('bf')),
        v_created_at,
        v_created_at,
        v_created_at,
        '{"provider":"email","providers":["email"]}'::jsonb,
        item->'raw_user_meta_data',
        v_created_at,
        v_updated_at
      );

      insert into auth.identities (
        user_id,
        provider_id,
        identity_data,
        provider,
        last_sign_in_at,
        created_at,
        updated_at
      ) values (
        v_user_id,
        item->>'email',
        jsonb_build_object(
          'sub', v_user_id::text,
          'email', item->>'email',
          'email_verified', true,
          'phone_verified', false
        ),
        'email',
        null,
        v_created_at,
        v_updated_at
      )
      on conflict (provider_id, provider) do update set
        user_id = excluded.user_id,
        identity_data = excluded.identity_data,
        updated_at = excluded.updated_at;
    else
      update auth.users
      set
        raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || (item->'raw_user_meta_data'),
        updated_at = greatest(updated_at, v_updated_at)
      where id = v_user_id;
    end if;

    update public.profiles
    set
      role = 'musician',
      display_name = item->>'display_name',
      email = item->>'email',
      avatar_url = nullif(item->>'avatar_url', '')
    where id = v_user_id;

    if not found then
      insert into public.profiles (
        id,
        role,
        display_name,
        email,
        avatar_url,
        created_at
      ) values (
        v_user_id,
        'musician',
        item->>'display_name',
        item->>'email',
        nullif(item->>'avatar_url', ''),
        v_created_at
      );
    end if;

    select id into v_existing_musician_profile_id
    from public.musician_profiles
    where profile_id = v_user_id
    order by created_at asc nulls last
    limit 1;

    if v_existing_musician_profile_id is null then
      insert into public.musician_profiles (
        profile_id,
        city,
        state,
        address,
        zip,
        formatted_address,
        instruments,
        instruments_detail,
        primary_instrument,
        experience_notes,
        gear_notes,
        is_volunteer,
        fee_min,
        fee_max,
        bio,
        available,
        travel_radius_miles,
        denomination_tags,
        music_format_tags,
        years_in_ministry,
        church_size_tags,
        paid_previously,
        practice_time_needed,
        lead_time_preference,
        profile_videos,
        youtube_links,
        created_at
      ) values (
        v_user_id,
        item->>'city',
        item->>'state',
        nullif(item->>'address', ''),
        nullif(item->>'zip', ''),
        nullif(item->>'formatted_address', ''),
        array(select jsonb_array_elements_text(item->'instruments')),
        item->'instruments_detail',
        item->>'primary_instrument',
        coalesce(item->>'experience_notes', ''),
        coalesce(item->>'gear_notes', ''),
        (item->>'is_volunteer')::boolean,
        (item->>'fee_min')::int,
        (item->>'fee_max')::int,
        coalesce(item->>'bio', ''),
        (item->>'available')::boolean,
        (item->>'travel_radius_miles')::int,
        array(select jsonb_array_elements_text(item->'denomination_tags')),
        array(select jsonb_array_elements_text(item->'music_format_tags')),
        nullif(item->>'years_in_ministry', '')::int,
        array(select jsonb_array_elements_text(item->'church_size_tags')),
        nullif(item->>'paid_previously', '')::boolean,
        nullif(item->>'practice_time_needed', ''),
        nullif(item->>'lead_time_preference', ''),
        item->'profile_videos',
        array(select jsonb_array_elements_text(item->'youtube_links')),
        v_created_at
      );
    else
      update public.musician_profiles
      set
        city = item->>'city',
        state = item->>'state',
        address = nullif(item->>'address', ''),
        zip = nullif(item->>'zip', ''),
        formatted_address = nullif(item->>'formatted_address', ''),
        instruments = array(select jsonb_array_elements_text(item->'instruments')),
        instruments_detail = item->'instruments_detail',
        primary_instrument = item->>'primary_instrument',
        experience_notes = coalesce(item->>'experience_notes', ''),
        gear_notes = coalesce(item->>'gear_notes', ''),
        is_volunteer = (item->>'is_volunteer')::boolean,
        fee_min = (item->>'fee_min')::int,
        fee_max = (item->>'fee_max')::int,
        bio = coalesce(item->>'bio', ''),
        available = (item->>'available')::boolean,
        travel_radius_miles = (item->>'travel_radius_miles')::int,
        denomination_tags = array(select jsonb_array_elements_text(item->'denomination_tags')),
        music_format_tags = array(select jsonb_array_elements_text(item->'music_format_tags')),
        years_in_ministry = nullif(item->>'years_in_ministry', '')::int,
        church_size_tags = array(select jsonb_array_elements_text(item->'church_size_tags')),
        paid_previously = nullif(item->>'paid_previously', '')::boolean,
        practice_time_needed = nullif(item->>'practice_time_needed', ''),
        lead_time_preference = nullif(item->>'lead_time_preference', ''),
        profile_videos = item->'profile_videos',
        youtube_links = array(select jsonb_array_elements_text(item->'youtube_links'))
      where id = v_existing_musician_profile_id;
    end if;

    insert into public.notification_preferences (profile_id)
    values (v_user_id)
    on conflict (profile_id) do nothing;
  end loop;
end $$;

commit;
